export function searchStocks(query: string, limit = 25): PSXStock[] {
  if (!query || !query.trim()) return ALL_PSX_STOCKS.slice(0, limit);
  const q = query.trim().toLowerCase();
  return ALL_PSX_STOCKS.filter(
    (s) =>
      s.symbol.toLowerCase().includes(q) ||
      s.name.toLowerCase().includes(q) ||
      s.sector.toLowerCase().includes(q)
  ).slice(0, limit);
}
